    "Univers": ["Univers", "Universes", "Universos"],
    "Carte": ["Carte", "Map", "Mapa"],
    "Carnet": ["Carnet", "Notebook", "Cuaderno"],
    "Préparation du voyage…": ["Préparation du voyage…", "Preparing your journey…", "Preparando tu viaje…"],
